import{_ as p,a0 as a,w as l,s as f,ao as n,I as r,x as o,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"浅议 Firefox 多账户容器 | LCTT x X-CMD","titleTemplate":false,"description":"浅议 Firefox 多账户容器 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"浅议 Firefox 多账户容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"浅议 Firefox 多账户容器 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20210809 What is Firefox Multi-Account Containers- Why and How to Use It","title":"浅议 Firefox 多账户容器","tag":"202208","desc":""},"relativePath":"202208/20210809 What is Firefox Multi-Account Containers- Why and How to Use It.md","filePath":"[post].md"}'),m={name:"202208/20210809 What is Firefox Multi-Account Containers- Why and How to Use It.md"};function u(d,t,x,g,C,h){const e=a("Link");return l(),f("div",null,[t[21]||(t[21]=n('<h1 id="浅议-firefox-多账户容器" tabindex="-1">浅议 Firefox 多账户容器 <a class="header-anchor" href="#浅议-firefox-多账户容器" aria-label="Permalink to “浅议 Firefox 多账户容器”">​</a></h1><p>随着在设备上使用各种程序的用户的需求变得越来越复杂，程序本身也需要跟上用户的现实需求和未来期望。</p><p>我发现我每天需要的东西是一个在网页浏览器保持登录多个账号的简单方法。我 <em>可以</em> 根据需要对我的每个账号进行登录和注销操作，但在短时间内切换多个账号时，这变得非常乏味。</p><p>最初，我使用谷歌浏览器，它拥有管理多个帐户的能力。这很有效，但管理起来略显繁琐，而且明明只需 <em>一个</em> 谷歌账号就能搞定的事却要创建一个新的谷歌账号来完成，这显得有点儿笨拙。</p><p>这是我转而使用 Firefox <ruby>多账户容器<rt>Multi-Account Containers</rt></ruby> 功能的原因。它不仅比我在谷歌 Chrome 浏览器上的设置灵活得多，而且我还使用了由我的浏览器开发者自己创建的工具，从而在整体上获得了更流畅和更简单的体验。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/Firefox-container.png?resize=800%2C450&amp;ssl=1" alt="Firefox 中的容器图示"></p><h3 id="firefox-中的多帐户容器是什么" tabindex="-1">Firefox 中的多帐户容器是什么？ <a class="header-anchor" href="#firefox-中的多帐户容器是什么" aria-label="Permalink to “Firefox 中的多帐户容器是什么？”">​</a></h3><p>如果你想将数字生活的各个部分彼此分开，多账户容器也非常有效。通过使用容器，你在一个容器中的浏览活动不会与其他容器共享。这种隔离意味着你可以在不同容器中登录同一网站上的两个不同帐户。你的登录会话、网站偏好和跟踪数据将被限制在你使用某个网站的容器中。</p><p>它还有什么其他优势？想象一下，你在亚马逊或其他电子商务网站上购物。你浏览了一些商品，但没有购买任何东西。现在，如果你浏览网络，你会看到与你浏览的产品相关的广告。尽管有广告拦截器，一些网站仍会显示广告。使用容器，你可以将你的购物网站与其他网站分开。（LCTT 校注：甚至根据你的浏览历史，你再次访问同一网站时看到的价格可能会被“宰熟”——反复浏览代表了你的购买倾向。）</p><p>再给大家分享一个例子。Firefox 默认提供一个 Facebook 容器。默认情况下，此容器包括 Facebook、Messenger 和 Instagram 网站。这意味着当你打开这三个网站中的任何一个时，它们都只会在“Facebook 容器”中打开。因此，Facebook 将无法跟踪你在其他网站上的活动。</p>',10)),r("p",null,[t[1]||(t[1]=o("这是 ",-1)),s(e,{href:"https://itsfoss.com/firefox-useful-features/"},{default:i(()=>[...t[0]||(t[0]=[o("很少有人知道或使用的 Firefox 功能",-1)])]),_:1}),t[2]||(t[2]=o(" 之一。",-1))]),t[22]||(t[22]=r("h3",{id:"使用多账户容器",tabindex:"-1"},[o("使用多账户容器 "),r("a",{class:"header-anchor",href:"#使用多账户容器","aria-label":"Permalink to “使用多账户容器”"},"​")],-1)),t[23]||(t[23]=r("p",null,"安装 Firefox 多账户容器是一个非常简单的过程，只需点击几下。",-1)),r("p",null,[t[4]||(t[4]=o("首先，前往 Firefox 附加组件网站上的 ",-1)),s(e,{href:"https://addons.mozilla.org/en-US/firefox/addon/multi-account-containers/?utm_source=addons.mozilla.org&utm_medium=referral&utm_content=search"},{default:i(()=>[...t[3]||(t[3]=[o("扩展程序页面",-1)])]),_:1}),t[5]||(t[5]=o("。之后你唯一需要做的就是单击 “添加到 Firefox” 按钮。",-1))]),t[24]||(t[24]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-install-page.png?resize=800%2C366&amp;ssl=1" alt=""></p><p>安装完成！现在我们可以实际使用一下这个新的扩展。</p><p>可能你还没有注意到，你的搜索栏右侧应该会出现一个新图标：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-searchbar-icon-1.png?resize=800%2C48&amp;ssl=1" alt=""></p><p>这是你将用于与 Firefox 多帐户容器交互的图标。如果你单击该图标，你将看到一个小菜单：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-main-menu.png?resize=302%2C474&amp;ssl=1" alt=""></p><p>让我们使用这个扩展尝试一些例子，看看多账户容器是如何工作的。</p><h4 id="设置容器" tabindex="-1">设置容器 <a class="header-anchor" href="#设置容器" aria-label="Permalink to “设置容器”">​</a></h4><p>首先，我们需要生成一个容器。点击多账户容器菜单中的 `<ruby>管理容器<rt>Manage Containers</rt></ruby>，然后点击 <ruby>新建容器<rt>New Container</rt></ruby>。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-manage-containers-1.png?resize=291%2C402&amp;ssl=1" alt=""></p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-new-container.png?resize=290%2C399&amp;ssl=1" alt=""></p><p>接着输入新容器的名称，选择颜色和图标。然后，点击 “OK” 保存新容器。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-new-container-itsfoss.png?resize=292%2C401&amp;ssl=1" alt=""></p><p>大功告成！我们现在可以返回主菜单在新容器中打开一个新选项卡：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-opening-new-container.png?resize=290%2C398&amp;ssl=1" alt=""></p><p>你还会注意到新选项卡有一些样式，表示它正在容器内运行：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-new-container-styling.png?resize=800%2C370&amp;ssl=1" alt=""></p><h4 id="观察容器工作" tabindex="-1">观察容器工作 <a class="header-anchor" href="#观察容器工作" aria-label="Permalink to “观察容器工作”">​</a></h4><p>现在让我们看看容器在使用时实际做了什么。</p><p>我们将在一个普通的浏览器选项卡中访问 Linode 管理网站，我已经在其中登录：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-linode.png?resize=800%2C114&amp;ssl=1" alt=""></p><p>现在让我们尝试在 Firefox 容器中打开相同的页面，此时我被重定向到 Linode 登录页面：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/08/firefox-containers-linode-login.png?resize=800%2C405&amp;ssl=1" alt=""></p><p>为什么我被重定向了？因为现在我没有登录。这就是 Firefox 容器的乐趣之一：在一个浏览器会话中登录后，再进入一个容器，就好像你以前从未访问过该站点一样。</p><p>如果你在容器内完成对某个网站的登录，你从容器中访问该网站时将会保持登录状态。你还可以使用此功能从容器内登录网站，从而使该网站的所有数据与你的正常浏览器数据相隔开。</p><blockquote><p>注意：你的浏览器历史记录本身之类的内容仍会暴露给你的正常浏览器会话。容器功能只是提供了一种方法来分离本文中提到的登录帐户等内容。</p></blockquote><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>对于那些在乎自己的隐私，或者只是想真正尝试对其系统的安全性进行严格控制的人来说，多账户容器被证明是一个很棒的功能。</p><p>例如，你可以在容器内登录你的谷歌帐户，谷歌永远不会知悉你在容器外的信息。 对拥有多个帐户的人来说，此扩展程序是一个不错的选择。有了它无需为你要使用的每样东西创建单独的浏览器帐户。</p><p>好了，这就是 Firefox 的多帐户容器的基本知识。</p><p>需要任何帮助，或者只是有点问题？请随时在评论区指出。</p><hr>',32)),r("p",null,[t[7]||(t[7]=o("via: ",-1)),s(e,{href:"https://itsfoss.com/firefox-containers/"},{default:i(()=>[...t[6]||(t[6]=[o("https://itsfoss.com/firefox-containers/",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=o("作者：",-1)),s(e,{href:"https://itsfoss.com/author/hunter/"},{default:i(()=>[...t[8]||(t[8]=[o("Hunter Wittenborn",-1)])]),_:1}),t[13]||(t[13]=o(" 选题：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[9]||(t[9]=[o("lujun9972",-1)])]),_:1}),t[14]||(t[14]=o(" 译者：",-1)),s(e,{href:"https://github.com/hanszhao80"},{default:i(()=>[...t[10]||(t[10]=[o("hanszhao80",-1)])]),_:1}),t[15]||(t[15]=o(" 校对：",-1)),s(e,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:i(()=>[...t[11]||(t[11]=[o("校对者ID",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[o("LCTT",-1)])]),_:1}),t[19]||(t[19]=o(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[o("Linux中国",-1)])]),_:1}),t[20]||(t[20]=o(" 荣誉推出",-1))])])}const b=p(m,[["render",u]]);export{T as __pageData,b as default};
